//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::lt`; the
//! native twin is `benches/native/Bench/StringLt.lean`.
//! Lean's Array.get! retains and releases the string it reads (an increment and a decrement of
//! its count); the Rust side borrows it

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::string;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<String>, n: u64) -> u64 {
    let ss = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let (a, b) = (get_str(ss, x >> 60), get_str(ss, (x >> 56) & 15));
            string::lt(a, b) as u64
        });
    }
    acc
}

fn main() {
    run(|| variants(), kernel)
}
